<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
        @if (isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in Messages)
        {
            var thread = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
            <MessageItem Message="message"
                         IsThreadStarter="thread is not null"
                         ReplyCount="thread?.ReplyCount ?? 0"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="message-compose">
        <textarea class="compose-input" @bind="newMessageContent" @bind:event="oninput"
                  placeholder="Message #@Channel.Name" @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageContent)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Channel Channel { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public List<ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    [Parameter]
    public bool HasMoreMessages { get; set; }

    private ElementReference messageListRef;
    private string newMessageContent = string.Empty;
    private bool isLoadingMore;

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers load more (handled via JS interop in production;
        // here we expose the callback for the parent to handle)
        if (HasMoreMessages && !isLoadingMore)
        {
            isLoadingMore = true;
            await OnLoadMore.InvokeAsync();
            isLoadingMore = false;
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageContent)) return;
        var content = newMessageContent;
        newMessageContent = string.Empty;
        await OnSendMessage.InvokeAsync(content);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }
}
