+}
+
+/* Message item */
+.message-item {
+    padding: 8px 12px;
+    border-radius: 6px;
+    position: relative;
+    margin-bottom: 4px;
+    transition: background 0.1s;
+}
+
+.message-item:hover {
+    background: #f8f9fa;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+}
+
+.message-author {
+    font-weight: 600;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #6c757d;
+}
+
+.message-content {
+    margin-top: 2px;
+    font-size: 0.9rem;
+    line-height: 1.4;
+}
+
+.message-reactions {
+    display: flex;
+    gap: 6px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #e9ecef;
+    border: 1px solid #dee2e6;
+    border-radius: 12px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: default;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #0d6efd;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message actions */
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 12px;
+    background: #fff;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 4px;
+    display: flex;
+    gap: 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    padding: 4px 8px;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+}
+
+.action-btn:hover {
+    background: #e9ecef;
+}
+
+/* Emoji picker */
+.emoji-picker {
+    position: absolute;
+    top: -8px;
+    right: 120px;
+    background: #fff;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    padding: 8px;
+    display: flex;
+    gap: 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
+    z-index: 10;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #e9ecef;
+}
+
+/* Compose area */
+.message-compose,
+.thread-compose {
+    padding: 12px 20px;
+    border-top: 1px solid #e0e0e0;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    background: #fff;
+}
+
+.compose-input {
+    flex: 1;
+    resize: none;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 8px 12px;
+    font-size: 0.9rem;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.compose-input:focus {
+    outline: none;
+    border-color: #0d6efd;
+    box-shadow: 0 0 0 2px rgba(13,110,253,0.15);
+}
+
+.send-btn {
+    background: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 16px;
+    font-size: 0.85rem;
+    font-weight: 600;
+    cursor: pointer;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+.chat-thread {
+    width: 25%;
+    min-width: 280px;
+    border-left: 1px solid #e0e0e0;
+    background: #fff;
+}
+
+.thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    font-weight: 700;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+    color: #6c757d;
+}
+
+.close-btn:hover {
+    background: #e9ecef;
+    color: #333;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #f8f9fa;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #495057;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+

